    @ExceptionHandler(CreditRejectedException.class)
    public ResponseEntity<ErrorResponse> handleCreditRejected(CreditRejectedException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new ErrorResponse("CREDIT_REJECTED"));
    }

    @ExceptionHandler(MemberAlreadyExistsException.class)
    public ResponseEntity<ErrorResponse> handleMemberAlreadyExists(MemberAlreadyExistsException e) {
